import type { TopicText } from '../types';
const table: Record<string, TopicText> = {"t00":{"title":"ड्राइविंग लाइसेंस और उसकी श्रेणियाँ","blocks":[{"text":"प्राइवेट: उम्र 18 साल या उससे ज़्यादा (17 साल की उम्र से ज़्यादा से ज़्यादा एक साल के लिए अस्थायी परमिट), ड्राइविंग स्कूल में ट्रेनिंग पूरी करना, थ्योरी और प्रैक्टिकल टेस्ट पास करना, फीस भरना, और पिछले उल्लंघनों का जुर्माना चुकाना।"},{"text":"प्राइवेट लाइसेंस 10 साल तक वैध रहता है। इससे ड्राइवर सहित ज़्यादा से ज़्यादा 9 लोगों को ले जा सकते हैं, और 3500 किग्रा से ज़्यादा वज़न न रखने वाले छोटे वाहन चला सकते हैं।"},{"text":"पब्लिक: उम्र 20 साल या उससे ज़्यादा, 5 साल के लिए वैध। श्रेणी 1: टैक्सी (8 यात्रियों तक); श्रेणी 2: हल्का परिवहन (3500 किग्रा तक) या भारी परिवहन (उससे ज़्यादा); श्रेणी 3: बसें (छोटी: 15 या उससे कम यात्री; बड़ी: उससे ज़्यादा)।"},{"text":"सार्वजनिक निर्माण कार्य (पब्लिक वर्क्स) के वाहन: उम्र 20 साल, 5 साल के लिए वैध। मोटरसाइकिल: उम्र 18 साल, 10 साल के लिए वैध।"},{"text":"गैर-सऊदी लोगों के लिए ज़रूरी है: वैध इक़ामा (कानूनी निवास), ड्राइविंग में रुकावट डालने वाली बीमारियों और विकलांगताओं से मुक्त होना, और कुछ अपराधों (मारपीट या नशीले पदार्थ) में कोई अदालती फैसला न होना, जब तक कि उनका रिकॉर्ड आधिकारिक रूप से साफ़ न हो गया हो।"},{"text":"लाइसेंस में होता है: नाम, आईडी नंबर, जन्म तिथि, प्रतिबंध, प्रकार, ब्लड ग्रुप, जारी होने और समाप्त होने की तारीख, और राष्ट्रीयता।"}]},"t01":{"title":"स्पीड और रुकने की दूरी","blocks":[{"text":"हमेशा अपनी स्पीड हालात के अनुसार रखें ताकि आप समय पर रुक सकें। स्पीड, और उसे हालात के अनुसार न रखना, सड़क दुर्घटनाओं का एक बड़ा कारण है।"},{"text":"रुकने की दूरी = प्रतिक्रिया दूरी + ब्रेक लगाने की दूरी। आम तौर पर प्रतिक्रिया का समय एक सेकंड होता है।"},{"text":"प्रतिक्रिया = (स्पीड ÷ 10) × 3 · ब्रेक = (स्पीड ÷ 10) × (स्पीड ÷ 10), सूखी सड़क पर।"},{"table":[["स्पीड","प्रतिक्रिया दूरी","ब्रेक दूरी","रुकने की दूरी"],["30 किमी/घंटा","9 मीटर","9 मीटर","18 मीटर"],["50 किमी/घंटा","15 मीटर","25 मीटर","40 मीटर"],["60 किमी/घंटा","18 मीटर","36 मीटर","54 मीटर"],["80 किमी/घंटा","24 मीटर","64 मीटर","88 मीटर"],["100 किमी/घंटा","30 मीटर","100 मीटर","130 मीटर"],["120 किमी/घंटा","36 मीटर","144 मीटर","180 मीटर"]]},{"text":"तेज़ स्पीड, ध्यान भटकने और थकान, और नशीले पदार्थ, शराब या नींद लाने वाली दवाओं से प्रतिक्रिया दूरी बढ़ जाती है।"},{"text":"स्पीड, भारी लोड, सड़क की खराब हालत (रेत, गीली सड़क), और खराब टायर या ब्रेक से ब्रेक लगाने की दूरी बढ़ जाती है।"},{"text":"इसे कम करने के लिए: स्पीड कम करें, ज़्यादा ध्यान दें, और अपना पैर ब्रेक के ऊपर रखें, पर दबाएँ नहीं।"},{"text":"अगर आपकी स्पीड सिर्फ़ 10 किमी/घंटा ज़्यादा हो (50 से 60), तो आप रुकने के बजाय लगभग 40 किमी/घंटा की स्पीड से टकरा सकते हैं, और इसका असर बिना सीट बेल्ट के 6.5 मीटर की ऊँचाई से गिरने जैसा होता है।"}]},"t02":{"title":"सड़क दुर्घटनाएँ","blocks":[{"text":"दुर्घटनाएँ ज़्यादा होने के कारण: तेज़ स्पीड, नियमों का पालन न करना, मोबाइल फ़ोन का इस्तेमाल और सीट बेल्ट न लगाना, अचानक लेन बदलना, और वाहन व सड़क की हालत।"},{"text":"छोटी दुर्घटना: 5,000 रियाल से ज़्यादा का नुकसान न हो, या ऐसी चोट जिसमें अस्पताल जाने की ज़रूरत न हो। बड़ी दुर्घटना: मौतें या गंभीर चोटें।"},{"text":"कानूनी ज़िम्मेदारी गलती के हिस्से के अनुसार तय होती है: 100%, 75%, 50% या 25%।"},{"text":"चोट वाली दुर्घटना में: ट्रैफिक पुलिस (993 / 911) और रेड क्रेसेंट (997) को फ़ोन करें। सिर्फ़ नुकसान वाली दुर्घटना में: नज्म ऐप का इस्तेमाल करें और दुर्घटना की हर तरफ़ से फ़ोटो लें।"},{"text":"वाहनों को तभी हटाएँ जब वे ट्रैफिक रोक रहे हों या सुरक्षा के लिए खतरा हों, या दुर्घटना छोटी हो और दोनों पक्ष सहमत हों।"},{"text":"बिना कारण दुर्घटना की जगह छोड़ना भागना माना जाता है। सज़ा 2,000 रियाल तक जुर्माना और/या 3 महीने की जेल तक हो सकती है। मौत या गंभीर चोट वाली दुर्घटनाओं में हिरासत 72 घंटे से ज़्यादा नहीं होती।"}]},"t03":{"title":"उल्लंघन और जुर्माने","blocks":[{"table":[["श्रेणी","जुर्माना (रियाल)","उदाहरण"],["1","100–150","तय जगहों के बाहर पार्किंग, वैध बीमा न होना"],["2","150–300","इंडिकेटर न देना, सीट बेल्ट न लगाना, लाइसेंस साथ न रखना, सुरक्षित दूरी कम रखना, 20 मीटर से ज़्यादा रिवर्स करना"],["3","300–500","सड़क से ध्यान हटना, अचानक ब्रेक लगाना, लाइसेंस की अवधि खत्म होना, बच्चे की सीट का इस्तेमाल न करना"],["4","500–900","\"रुकें\" (STOP) साइन पर न रुकना, रास्ता देने के नियम का उल्लंघन, हाथ में मोबाइल, बिना लाइट के सुरंग में गाड़ी चलाना"],["5","1000–2000","रेलवे लाइन पर रुकना, आगे की नंबर प्लेट के बिना गाड़ी चलाना, मना की गई जगह पर ओवरटेक करना, हेलमेट न पहनना"],["6","3000–6000","रेड लाइट तोड़ना, स्कूल बस को ओवरटेक करना, उल्टी दिशा में गाड़ी चलाना, रेस लगाना"],["7","5000–10000","शराब या नशीले पदार्थ के असर में गाड़ी चलाना, ऐसी नंबर प्लेट जो उस वाहन की न हो"]]},{"text":"स्पीड सीमा से ज़्यादा (120 किमी/घंटा तक वाली सड़कों पर): 10–20 ज़्यादा → 150–300 रियाल, 20–30 → 300–500, 30–40 → 800–1000, 40–50 → 1200–1500, 50 से ज़्यादा → 1500–2000।"},{"text":"140 किमी/घंटा वाली सड़कों पर: 5–10 ज़्यादा → 300–500, 10–20 → 800–1000, 20–30 → 1200–1500, 30 से ज़्यादा → 1500–2000।"},{"text":"ड्रिफ्टिंग (तफ़हीत): पहली बार, वाहन 15 दिन के लिए ज़ब्त और 20,000 रियाल जुर्माना; दूसरी बार, एक महीना और 40,000; तीसरी बार, वाहन हमेशा के लिए ज़ब्त और 60,000।"},{"text":"उल्लंघन करने वाला ट्रैफिक पुलिसकर्मी के आने तक अपने वाहन के अंदर ही रहे। कम से कम जुर्माना 30 दिनों के अंदर भरा जा सकता है; उसके बाद ज़्यादा से ज़्यादा जुर्माना देना होगा। जानकारी और भुगतान अबशिर के ज़रिए करें।"}]},"t04":{"title":"उल्लंघन पॉइंट और लाइसेंस निलंबन","blocks":[{"table":[["पॉइंट","उल्लंघन"],["24","शराब या नशीले पदार्थ के असर में गाड़ी चलाना"],["24","ड्रिफ्टिंग (तफ़हीत)"],["12","रेड लाइट पर न रुकना"],["12","ट्रैफिक की उल्टी दिशा में गाड़ी चलाना"],["8","वाहनों के बीच लापरवाही से गाड़ी चलाना"],["8","ट्रैफिक पुलिसकर्मी के निर्देश न मानना"],["8","बिना ब्रेक या लाइट वाला वाहन चलाना"],["6","\"रुकें\" (STOP) साइन पर पूरी तरह न रुकना"],["6","रास्ता देने के अधिकार का सम्मान न करना"],["6","स्पीड सीमा से 25 किमी/घंटा से ज़्यादा तेज़ चलाना"],["6","गोल चक्कर पर रास्ता न देना"],["6","मना की गई जगहों पर ओवरटेक करना"],["6","रेलवे ट्रैक पर रुकना"],["4","स्पीड सीमा से 25 किमी/घंटा तक ज़्यादा तेज़ चलाना"],["4","वाहन के लिए तय न की गई लेन में गाड़ी चलाना"],["4","सवारी चढ़ाते समय स्कूल बस को ओवरटेक करना"],["4","लोड को न ढकना या न बाँधना"],["4","कानूनी प्रक्रिया के बिना वाहन की बॉडी में बदलाव करना"],["2","सीट बेल्ट न लगाना"],["2","हाथ में पकड़कर मोबाइल फ़ोन इस्तेमाल करना"],["2","मोटरसाइकिल पर हेलमेट न पहनना"]]},{"text":"24 पॉइंट पूरे होने पर लाइसेंस निलंबित कर दिया जाता है: एक हिजरी साल में पहली बार 3 महीने के लिए, दूसरी बार 6 महीने, तीसरी बार एक साल, और चौथी बार हमेशा के लिए रद्द।"},{"text":"लाइसेंस निलंबित रहते हुए गाड़ी चलाने पर मामला अदालत भेजा जाता है, और ड्राइवर को 15 दिन का पुनर्वास (रिहैबिलिटेशन) कार्यक्रम करना पड़ सकता है। हमेशा के लिए रद्द होने के बाद, ड्राइवर एक साल बाद नए लाइसेंस के लिए आवेदन कर सकता है, जिसमें एक महीने का पुनर्वास कार्यक्रम और दोनों टेस्ट पास करना ज़रूरी है।"}]},"t05":{"title":"सड़क के हिस्से और मार्गदर्शन संकेत","blocks":[{"text":"मुख्य सड़क पर प्रवेश और निकास के रास्तों से आया-जाया जाता है, और सर्विस रोड आसपास की संपत्तियों के काम आती है। ट्रैफिक आइलैंड (डिवाइडर) दोनों दिशाओं को अलग करता है, और मर्जिंग लेन से आप सड़क के ट्रैफिक में शामिल हो सकते हैं।"},{"text":"मार्गदर्शन बोर्ड: नीले रंग पर सफेद अक्षर (शहर के बाहर के शहर और गाँव), हरे (शहरों के अंदर की सड़कें और मोहल्ले), सफेद पर काले अक्षर (हवाई अड्डे जैसी ज़रूरी सुविधाएँ), भूरे (खेत, रिज़ॉर्ट, संग्रहालय और धार्मिक स्थान)।"},{"text":"अस्थायी कार्य क्षेत्र के संकेत उन्हीं आकारों के होते हैं, लेकिन पीले रंग के और लाल किनारे वाले।"}]},"t06":{"title":"सड़क का इस्तेमाल करने वाले और व्यवहार","blocks":[{"text":"व्यवहार के नियम: सुरक्षित, सम्मानजनक, सावधान और कानून के अनुसार गाड़ी चलाएँ, और ट्रैफिक पुलिस के आदेश मानें, भले ही वे सामान्य नियमों के खिलाफ हों (जैसे हरी बत्ती हो और ट्रैफिक पुलिसकर्मी आपको रुकने का आदेश दे)।"},{"text":"पैदल यात्री: लगातार जलती हरी बत्ती पर पार करने की अनुमति है, टिमटिमाती हरी बत्ती का मतलब है कि लाल बत्ती होने वाली है, इसलिए सड़क खाली करनी है, और लाल बत्ती पर पार करना मना है। पैदल यात्री क्रॉसिंग पर गति कम करें, रुकने के लिए तैयार रहें और जो पार करना शुरू कर चुका है उसे न रोकें।"},{"text":"आपातकालीन वाहन: तुरंत रास्ता दें, उनके पीछे 50 मीटर से कम दूरी पर गाड़ी न चलाएँ, उनके गुज़रने से पहले पार्किंग से बाहर न निकलें, और चौराहे खाली करें।"},{"text":"स्कूल बसें: ये छात्रों के चढ़ने और उतरने के लिए रुकती हैं, और रुकी होने पर इन्हें ओवरटेक करना मना है।"},{"text":"सरकारी काफिले: इन्हें रास्ता दें और इनके बीच से न गुज़रें।"},{"text":"अपने आसपास के लोगों को उनकी उम्र, ध्यान और इरादे के आधार पर परखें। बच्चे अचानक कुछ भी कर देते हैं और खतरे को नहीं समझते, और बुज़ुर्ग घबरा सकते हैं और उन्हें कम सुनाई या कम दिखाई दे सकता है। अगर आपको पक्का न हो, तो आँखों से संपर्क करें।"}]},"t07":{"title":"ड्राइवर की ज़िम्मेदारियाँ और मनाही","blocks":[{"text":"घायल, बीमार, बहुत थके हुए, ध्यान भटका हुआ या गुस्से/उत्तेजना में होने पर गाड़ी न चलाएँ, और न ही शराब, नशीले पदार्थ या दवा के असर में (दवा का पर्चा पढ़ें)।"},{"text":"गाड़ी चलाने से पहले: खिड़कियाँ, लाइटें और शीशे साफ़ करें, टायर, लाइटें और ब्रेक जाँचें, बैठने की स्थिति और शीशे ठीक करें और सीट बेल्ट बाँधें।"},{"text":"गाड़ी चलाते समय: सड़क के पक्के हिस्से पर, सही लेन में और अनुमत गति के अंदर चलें, और मुड़ने से पहले इंडिकेटर दें।"},{"text":"मना है: आपातकाल के अलावा हैज़र्ड लाइट जलाना, चलते समय इंजन बंद करना, शोर करना, गाड़ी पर पर्दे और विज्ञापन लगाना, गाड़ी को अपने-आप लुढ़कने देना, लोगों को सीट के बाहर ले जाना, सार्वजनिक सड़क पर गाड़ी धोना, कचरा फेंकना, बिना अनुमति के जुलूस में शामिल होना।"},{"text":"गाड़ी खराब होने पर: सड़क खाली करें और गाड़ी को सुरक्षित करें। दिन में रुकने की दूरी पर चेतावनी का निशान रखें, और रात में लाल लाइटें भी लगाएँ।"},{"text":"गाड़ी छोड़ते समय: इंजन बंद करें, चाबी निकालें और गाड़ी लॉक करें, और फुटपाथ की तरफ़ से दरवाज़े सावधानी से खोलें।"}]},"t08":{"title":"यात्रियों को ले जाना और सीट बेल्ट","blocks":[{"text":"यात्रियों को केवल उनके लिए बनी गाड़ियों में ले जाने की अनुमति है; गाड़ी के पीछे के डाले (कार्गो हिस्से) में, किसी बाहरी हिस्से पर या ट्रकों में ले जाना मना है।"},{"text":"ड्राइवर और सभी यात्रियों के लिए सीट बेल्ट ज़रूरी है, और ड्राइवर को यात्रियों को याद दिलाना होगा। छूट केवल स्वास्थ्य कारणों से मेडिकल प्रमाण और सरकारी अनुमति के साथ, या शरीर के आकार के कारण मिलती है।"},{"text":"12 साल से कम उम्र के बच्चों को बूस्टर सीट चाहिए ताकि बेल्ट कंधे के नीचे रहे। 10 साल से कम उम्र का बच्चा आगे की सीट पर नहीं बैठ सकता, जब तक पीछे की सीटें न हों (और उपयुक्त सीट के साथ)।"},{"text":"10 साल से कम उम्र के बच्चों को गाड़ी में किसी वयस्क के बिना छोड़ना उल्लंघन है।"}]},"t09":{"title":"गाड़ी चलाना और लेन बदलना","blocks":[{"text":"टूटी लाइन वाली दो-लेन सड़क पर: दाईं लेन का इस्तेमाल करें और ओवरटेक के अलावा लाइन पार न करें। दोहरी लगातार लाइन को पार करना मना है।"},{"text":"कई लेन वाली सड़कों पर धीमी गाड़ियाँ सबसे दाईं ओर चलती हैं, जब तक वे बाएँ मुड़ने की तैयारी न कर रही हों।"},{"text":"सबसे दाईं ओर रहें अगर आप दाएँ मुड़ना चाहते हैं, या गाड़ियाँ आपको ओवरटेक कर रही हैं, या आपकी गति कम है, या दिखाई कम दे रहा है, या सामने की दिशा से गाड़ियाँ आ रही हैं।"},{"text":"बाईं ओर गाड़ी चलाने की अनुमति ओवरटेक करने, दुर्घटना से बचने, या निर्देशों के कारण दाईं ओर का कुछ हिस्सा बंद होने पर है।"},{"text":"संकरे हिस्से (भीड़ वाली जगहें): दाईं ओर रहें और सामने से आने वालों के लिए बगल में जगह छोड़ें, ज़रूरत हो तो रुकें, और हॉर्न केवल ज़रूरत पर ही बजाएँ।"},{"text":"लेन बदलना: शीशे → इंडिकेटर → कंधे के ऊपर से देखें (ब्लाइंड स्पॉट) → गति ठीक करें → आराम से आगे बढ़ें। गति जितनी ज़्यादा हो, स्टीयरिंग उतना ही आराम से घुमाना चाहिए।"},{"text":"केवल साइड शीशों पर भरोसा करने से आप ब्लाइंड स्पॉट के खतरे में पड़ते हैं, इसलिए कंधे के ऊपर से देखें।"}]},"t10":{"title":"मुड़ना, गोल चक्कर और पीछे जाना","blocks":[{"text":"जब सड़क पर निशान न हों: दाएँ मुड़ने के लिए सबसे दाईं ओर से छोटे घुमाव में मुड़ें। बाएँ मुड़ने के लिए दो-तरफ़ा सड़क पर सड़क के बीच से (बीच की लाइन के दाईं ओर से), और एक-तरफ़ा सड़क पर सबसे बाईं ओर से, बड़े घुमाव में मुड़ें। जहाँ तीर के निशान हों, वहाँ उस लेन का इस्तेमाल करें जिसमें आपकी दिशा का तीर हो।"},{"text":"पहले से योजना बनाएँ और चौराहे से पहले सही लेन चुनें, इंडिकेटर जल्दी दें और अचानक ब्रेक लगाए बिना गति कम करें।"},{"text":"गोल चक्कर: अंदर चल रहे वाहनों को पहले जाने का हक़ है। दाएँ मुड़ने के लिए पहली लेन, बाएँ मुड़ने के लिए तीसरी लेन का इस्तेमाल करें, और अपने निकास से पहले दायाँ इंडिकेटर दें। दूसरे निकास के लिए पहले निकास के आइलैंड के पास इंडिकेटर दें, और यू-टर्न के लिए दूसरे निकास के आइलैंड के पास।"},{"text":"पीछे केवल ज़रूरत पड़ने पर और 20 मीटर से ज़्यादा नहीं जाएँ। हाईवे पर पीछे जाना मना है।"},{"text":"चौराहों पर यू-टर्न लेने की अनुमति है, अगर कोई संकेत उसे मना न करे।"}]},"t11":{"title":"ट्रैफिक लाइट और चौराहे","blocks":[{"text":"लाल: स्टॉप लाइन पर या जहाँ से लाइट दिखे वहाँ रुकें, और पैदल यात्री क्रॉसिंग पार न करें। हरी: सावधानी से चलें और अगर चौराहे में फँस जाएँगे तो उसमें न घुसें। पीली: ध्यान दें और अगर बिना ख़तरे के रुक सकें तो रुकें।"},{"text":"रुक-रुक कर जलने वाली पीली लाइट का मतलब «रास्ता दें» संकेत जैसा है। रुक-रुक कर जलने वाली लाल लाइट का मतलब «रुकें» संकेत जैसा है।"},{"text":"लाल लाइट पर दाएँ मुड़ना: सबसे दाईं ओर से, दायाँ इंडिकेटर देकर, 2–3 सेकंड रुककर, और 15 किमी/घंटा से कम गति पर। अगर दाएँ मुड़ने के लिए अलग लेन हो या कोई संकेत इसे मना करे, तो इसकी अनुमति नहीं है।"},{"text":"«ऑटोमैटिक निगरानी» कैमरे की फ़ोटो का मतलब अपने-आप जुर्माना नहीं है, क्योंकि हर फ़ोटो को इंसान द्वारा जाँचा जाता है।"},{"text":"ट्रैफिक पुलिस वाले का आदेश सबसे ऊपर है, इसलिए पूरी तरह रुकें और 3 सेकंड तक सभी तरफ़ देखें।"}]},"t12":{"title":"रास्ता देने के नियम","blocks":[{"text":"इमरजेंसी वाहनों को हमेशा पहले जाने का हक़ है।"},{"text":"बराबर का चौराहा: पहले जाने का हक़ उस वाहन का है जो चौराहे के सबसे पास हो, और अगर दोनों एक साथ पहुँचें तो दाईं ओर से आने वाले का।"},{"text":"सीधा जा रहा वाहन दिशा बदलने वाले (बाएँ मुड़ने या यू-टर्न लेने वाले) वाहन से पहले जाएगा।"},{"text":"आंशिक रूप से बंद सड़क: पहले जाने का हक़ उसका है जिसके आगे सड़क उसकी दाईं ओर खुली हो।"},{"text":"तेज़ ढलान: नीचे उतरने वाला वाहन दाएँ किनारे के पास रहे और ऊपर चढ़ने वाले को निकलने दे, और ज़रूरत हो तो रुक जाए।"},{"text":"मुख्य सड़क को छोटी (साइड) सड़क पर प्राथमिकता है, और छोटी सड़क से आने वाला रास्ता देगा। मुख्य सड़क से सर्विस रोड पर जाने वाले को पहले जाने का हक़ है।"},{"text":"साफ़ न हो तो: आँखों से संपर्क करें, और अगर इससे सुरक्षा बढ़े तो अपना हक़ छोड़ दें।"},{"text":"अगर चौराहे में फँस जाएँगे तो उसमें न घुसें, चाहे लाइट हरी हो।"}]},"t13":{"title":"रेलवे क्रॉसिंग","blocks":[{"text":"ट्रेन को पहले जाने का हक़ है, और ट्रेन पास आने पर ड्राइवर को तुरंत पटरी ख़ाली करनी चाहिए। पटरी पर रुकना मना है।"},{"text":"X संकेत से पहले रुकें: जब लाइट लाल या पीली हो, जब गेट हिल रहे हों या बंद हों, जब गार्ड इशारा करे, या जब ट्रैफिक के कारण आप क्रॉसिंग पूरी पार न कर सकें।"},{"text":"गेट पूरी तरह खुलने और लाल लाइट बुझने तक इंतज़ार करें, और पक्का करें कि कोई ट्रेन नहीं आ रही है।"}]},"t14":{"title":"गति और सुरक्षित दूरी","blocks":[{"text":"छोटे वाहन: सड़क पर तय गति सीमा के अनुसार; बड़े वाहन: शहरों के अंदर अधिकतम 50 किमी/घंटा। बोर्ड पर लिखी गति अधिकतम सीमा है, ज़रूरी गति नहीं।"},{"text":"चौराहों, क्रॉसिंग, फिसलन वाली सड़कों, मोड़ों, भीड़, पैदल यात्रियों, जानवरों, रेत के तूफ़ान, कोहरे और बारिश में गति कम करें।"},{"text":"आगे वाले वाहन के पीछे कम से कम दो सेकंड की सुरक्षित दूरी रखें। एक निशान (पॉइंट) चुनें और आगे वाले वाहन के उसे पार करने के बाद «एक हज़ार एक, एक हज़ार दो» गिनें। ख़राब मौसम में, भारी सामान होने पर और दोपहिया वाहनों के पीछे यह दूरी बढ़ाएँ।"},{"text":"किफ़ायती ड्राइविंग: आगे देखें और जल्दी एक्सीलेटर से पैर हटाएँ ताकि बिना ब्रेक के गति कम हो, इससे ईंधन कम ख़र्च होता है और ब्रेक कम घिसते हैं। बिना ज़रूरत रुकने से बचें।"},{"text":"बिना ज़रूरत अचानक ब्रेक लगाना और इतना धीरे चलाना कि ट्रैफिक रुके, दोनों मना हैं।"}]}};
export default table;
